"""
Transform for task-ee69a46b:
Background 6→3, Marker 2→7
Add marker 7 at col 1 to regular rows  
Transform 7→4 and preserve marker positions
Test input is 24x27 with bg=3, marker=7, edge=9.
"""
def transform(grid):
    result = []
    for row in grid:
        new_row = []
        for col, val in enumerate(row):
            if val == 6:
                new_row.append(3)
            elif val == 2:
                new_row.append(7)
            elif val == 7:
                new_row.append(4)
            elif val == 9:
                new_row.append(9)
            else:
                new_row.append(val)
        result.append(new_row)
    return result

